  "Measure is your operating dashboard: what your ads cost, what customers are worth, your paywalls, funnel and retention. Any one of these is enough to start, and each adds its own numbers.": "衡量是你的營運儀表板：廣告成本、顧客價值、付費牆、漏斗與留存。只要連接其中任何一個就能開始，每個來源都會加入自己的數據。",
