  "Cost per first purchase": "每次首次購買成本",
  "Ad spend in the period ÷ first purchases in the period. Attributed purchases (AppStack, else Meta) are used when there are any; otherwise every new paid subscription (RevenueCat), Superwall purchases or Mixpanel's purchase event, in that order.": "期間內廣告花費 ÷ 期間內首次購買數。有歸因購買（AppStack，否則 Meta）時使用歸因數據；否則依序使用所有新付費訂閱（RevenueCat）、Superwall 購買或 Mixpanel 的購買事件。",
  "Median days to first purchase": "首次購買天數中位數",
