  "Connect RevenueCat to see the spread, not just the mean.": "連接 RevenueCat 即可看到分布，而不只是平均值。",
  "CAC to LTV": "CAC 與 LTV",
  "LTV basis: {basis}": "LTV 依據：{basis}",
  "LTV per paying customer": "每位付費顧客 LTV",
  "LTV ÷ CAC. CAC is the headline cost per paying customer (or the cost per first purchase when there's no headline). Above 1 a customer earns back what they cost; 3 is the usual healthy mark.": "LTV ÷ CAC。CAC 為主要的每位付費顧客成本（沒有時則用每次首次購買成本）。大於 1 表示顧客能賺回其成本；3 是常見的健康水準。",
  "Blended: ad spend ÷ every new paying customer the source counted, organic included. Real paid CAC is at or above it.": "混合：廣告花費 ÷ 該來源統計的所有新付費顧客（含自然流量）。實際付費 CAC 會等於或高於此數。",
  "Ad spend ÷ paying customers attributed to the ads.": "廣告花費 ÷ 歸因於廣告的付費顧客數。",
  "LTV per trial start": "每次試用開始 LTV",
  "LTV per install": "每次安裝 LTV",
  "LTV per trial start × the share of installs who start a trial. Compare it with your CPI.": "每次試用開始 LTV × 開始試用的安裝比例。可與你的 CPI 比較。",
  "Realized LTV (cohorts)": "實現 LTV（同期群）",
