  "Trial starts ÷ installs. Prefilled from RevenueCat or Superwall trials (else Mixpanel or attribution) over the same installs.": "試用開始數 ÷ 安裝數。預填自 RevenueCat 或 Superwall 的試用（否則使用 Mixpanel 或歸因數據），以相同的安裝數計算。",
  "Trial to paid": "試用轉付費",
  "Trials that convert to paid. Prefilled from RevenueCat's trial conversion rate, else paid ÷ trials from one source.": "轉為付費的試用比例。預填自 RevenueCat 的試用轉換率，否則用同一來源的付費 ÷ 試用。",
  "Monthly churn": "月流失率",
  "Share of monthly subscribers lost each month (weekly and quarterly plans follow it too). Prefilled from RevenueCat's churn chart.": "每月流失的月訂閱者比例（每週與每季方案也依此計算）。預填自 RevenueCat 的流失圖表。",
  "Annual renewal": "年續訂率",
  "Share of annual subscribers who renew after a year. RevenueCat needs a year of history to show it, so it starts at a typical 35%.": "一年後續訂的年度訂閱者比例。RevenueCat 需要一年的歷史資料才能顯示，因此預設為常見的 35%。",
  "Refund rate": "退款率",
  "Share of revenue refunded. Prefilled from RevenueCat's refund rate, else Superwall's refunds ÷ revenue.": "被退款的營收比例。預填自 RevenueCat 的退款率，否則用 Superwall 的退款 ÷ 營收。",
  "Store fee": "商店抽成",
  "The store's cut of each charge: 15% in the App Store Small Business Program and Google Play's first $1M (and for subscriptions after a year), 30% otherwise.": "商店對每筆扣款的抽成：App Store 小型企業計畫與 Google Play 前 100 萬美元（以及滿一年後的訂閱）為 15%，其他情況為 30%。",
  "Plans and price mix": "方案與價格組合",
  "Gross price and share of new paying customers for each plan. Prefilled from RevenueCat's proceeds and new paid subscriptions by product duration, grossed back up by the store fee (an estimate: proceeds also hold renewals).": "各方案的總價格與新付費顧客佔比。預填自 RevenueCat 依產品期間區分的實收與新付費訂閱，並以商店抽成還原為總價（為估計值：實收也包含續訂）。",
