  "Remove plan": "移除方案",
  "Add a plan": "新增方案",
  "Next 12 months": "未來 12 個月",
  "Steady spend, new payers each month, renewals stacking up. The band: conversion 20% worse or better, churn 25% higher or 20% lower.": "花費穩定、每月新增付費者、續訂逐步累積。區間：轉換率差或好 20%，流失率高 25% 或低 20%。",
  "Subscribers": "訂閱者",
  "Paying subscribers at the end of month 12: every month's new payers, less those who churned or didn't renew (lifetime buyers count as kept).": "第 12 個月底的付費訂閱者：每月的新付費者，扣除流失或未續訂者（終身方案購買者視為留存）。",
  "Revenue (12 mo)": "營收（12 個月）",
  "Net revenue over the 12 months: every charge after the store's fee and refunds.": "12 個月的淨營收：每筆扣款扣除商店抽成與退款後的金額。",
  "Profit (12 mo)": "利潤（12 個月）",
