  "When one month's new payers have earned back that month's ad spend (CAC = CPI ÷ (install to trial × trial to paid)).": "某個月的新付費者賺回該月廣告花費的時間（CAC = CPI ÷（安裝轉試用 × 試用轉付費））。",
