  "An analysis collects accounts' recent posts and reads what works in them: formats, hooks and what the audience asks for.": "分析會收集帳號近期的貼文，解讀其中有效的部分：格式、開場鉤子，以及受眾想要什麼。",
  "An analysis is running": "有分析正在執行",
