  "Analyses": "分析",
  "App settings": "App 設定",
  "Appearance": "外觀",
  "Ask the owner to add it in Settings.": "請擁有者在「設定」中新增。",
  "Back to app": "返回 App",
  "Bring an ad you like, say what to change and add your own pictures: new versions come back in its exact style for {name}. Or describe a shot and make a video.": "帶來一則你喜歡的廣告，說明要改什麼並加入自己的圖片：就會以完全相同的風格為 {name} 做出新版本。也可以描述一個畫面來製作影片。",
