  "Created in your ad account but switched off: nothing spends until you turn it on in Ads Manager.": "已建立在你的廣告帳號中但處於關閉狀態：在廣告管理員中開啟之前不會產生任何花費。",
  "Creatives": "素材",
  "Customer acquisition cost: what you spent on ads for each new paying customer.": "顧客取得成本：每獲得一位新的付費顧客所花的廣告費。",
