  "Desktop runner": "桌面執行程式",
  "Each app keeps its own research, creatives, ads and numbers.": "每個 App 都有各自的研究、素材、廣告與數據。",
  "Every analysis of social posts, for each app and the ones that name none. Each app's own are also under its Research › Social posts.": "所有社群貼文分析，包括各 App 的以及未指定 App 的。各 App 自己的分析也在其「研究 › 社群貼文」中。",
  "Every app at once, with its numbers and next step.": "一次查看所有 App 的數據與下一步。",
  "Every app in this workspace: how each one is doing and what to do next.": "此工作區中的所有 App：各自的表現以及下一步該做什麼。",
  "Find my competitors": "找出我的競品",
  "Free up space before it fills.": "在空間用完前先釋出空間。",
  "Free up space to keep saving ads and creatives.": "釋出空間，才能繼續儲存廣告與素材。",
  "General & plan": "一般與方案",
