  "Guides for each key": "各金鑰的教學",
  "Help": "說明",
  "Hide {name}'s pages": "隱藏 {name} 的頁面",
  "How many months until a customer has paid back what it cost to win them.": "顧客需要幾個月才能付回取得他們所花的成本。",
  "How much of your storage is used, by app and by kind, and what to delete to free space.": "各 App、各類型使用了多少儲存空間，以及可以刪除哪些內容來釋出空間。",
  "How the app is doing, and the one thing to do next.": "App 的表現，以及接下來最該做的一件事。",
  "It is set on the server for this workspace.": "此工作區的金鑰設定在伺服器上。",
  "Keyboard shortcuts": "鍵盤快捷鍵",
  "Kind of analysis": "分析類型",
  "Leave these empty unless you want this app's files in a folder of your own.": "除非你想把此 App 的檔案放在自己的資料夾，否則請留空。",
  "Lifetime value divided by acquisition cost. Above 3 is healthy; below 1 loses money on every customer.": "終身價值除以取得成本。高於 3 代表健康；低於 1 代表每位顧客都在虧錢。",
  "Lifetime value: what one paying customer pays you over time.": "終身價值：一位付費顧客長期下來付給你的金額。",
  "Light": "淺色",
  "Main": "主要",
  "Make your own ads from what works, in your brand.": "依照有效的做法，以你的品牌製作自己的廣告。",
  "Match the device": "跟隨裝置",
  "Match the device's theme": "跟隨裝置的主題",
  "Members": "成員",
  "Menu": "選單",
  "Menus, pages and messages. Your competitors' ads and your own copy stay in the language they were written in.": "選單、頁面與訊息。競品的廣告和你自己的文案會維持原本撰寫的語言。",
