  "New creatives land here once they have been checked. Start a batch in New batch above, or remix an ad on the Remix tab.": "新素材檢查完成後會出現在這裡。在上方的「新批次」開始一個批次，或在「混搭」分頁混搭一則廣告。",
  "New": "新增",
