  "Send approved ads to your Meta ad account, paused until you switch them on.": "把核准的廣告送到你的 Meta 廣告帳號，在你開啟之前都會保持暫停。",
  "Settings": "設定",
  "Show {name}'s pages": "顯示 {name} 的頁面",
  "Social posts": "社群貼文",
  "Start a batch in New batch above, or remix an ad on the Remix tab: they're reviewed here.": "在上方的「新批次」開始一個批次，或在「混搭」分頁混搭一則廣告：成果都會在這裡審核。",
  "Start with your competitors: the analysis finds them from your app's profile and reads what wins for them on each channel.": "從競品開始：分析會根據你的 App 簡介找出競品，並解讀他們在各個管道上成功的做法。",
  "Step by step: where to find each key and ID, and what it costs. Add them under Settings › Your keys.": "逐步說明：每個金鑰與 ID 在哪裡找、要花多少錢。請到「設定 › 你的金鑰」新增。",
  "Storage is almost full": "儲存空間快滿了",
  "Storage is full": "儲存空間已滿",
  "Storage {percent} full": "儲存空間已使用 {percent}",
  "Stuck, or something looks wrong? Write to us and say what you were doing.": "卡住了，或看起來有問題？寫信給我們，並說明你當時在做什麼。",
  "Templates": "範本",
  "The accounts {name}'s pages work from: Meta for ads, and RevenueCat, Superwall, Mixpanel or AppStack for what customers earn.": "{name} 的頁面所使用的帳號：Meta 用於廣告，RevenueCat、Superwall、Mixpanel 或 AppStack 用於顧客帶來的營收。",
  "The ads, apps and posts that work for your competitors.": "對競品有效的廣告、App 與貼文。",
  "The app's profile, brand and connected accounts.": "App 的簡介、品牌與連接的帳號。",
