  "The last step stopped": "最後一個步驟已停止",
  "The part of a Meta campaign that holds the budget, audience and placements; its ads sit inside it.": "Meta 行銷活動中負責預算、受眾與版位的部分；廣告就放在其中。",
  "The services this workspace uses. Each key is checked when you save it and kept in your own Supabase project.": "此工作區使用的服務。每個金鑰在儲存時都會檢查，並保存在你自己的 Supabase 專案中。",
  "The steps to set up your app, one at a time.": "一步一步設定你的 App。",
