  "Their ads": "他們的廣告",
  "This workspace's name, your plan and how much of it is used.": "此工作區的名稱、你的方案以及使用量。",
  "Turn a brief, a winning format or a competitor's ad into videos and image ads. Each one is checked against your brand's rules, and only the ones you approve can launch. {n} approved so far.": "把簡報、成功的格式或競品的廣告變成影片與圖片廣告。每一則都會依照你的品牌規則檢查，只有你核准的才能投放。目前已核准 {n} 則。",
  "Updates": "更新",
  "Use the dark theme": "使用深色主題",
  "Use the light theme": "使用淺色主題",
  "What each page does": "各頁面的用途",
  "What each page of {name} does": "{name} 各頁面的用途",
  "What every creative for {name} follows, and the pictures it uses. The essentials are here; the rest is under More detail.": "{name} 的每則素材都要遵循的規範，以及會用到的圖片。重點在這裡，其餘在「更多細節」。",
  "What works in competitors' and creators' own posts on Instagram, TikTok and YouTube: formats, hooks and what their audience asks for. Every run is kept.": "競品與創作者在 Instagram、TikTok、YouTube 自己的貼文中有效的做法：格式、開場鉤子，以及受眾想要什麼。每次執行都會保留。",
  "What your ads cost next to what customers pay you.": "廣告花費與顧客付給你的金額並列比較。",
  "What {name} is and who it's for: your profile, and the AI's fuller read of your links.": "{name} 是什麼、為誰而做：你的簡介，以及 AI 對你連結更完整的解讀。",
