  "Approved creatives arrive in your own Meta ad account as {paused} ads, in a campaign and an {adSet}. Nothing spends until you switch them on in Ads Manager.": "核准的素材會以{paused}廣告的形式，放進你自己的 Meta 廣告帳號中的行銷活動與{adSet}。在廣告管理員中開啟之前不會產生任何花費。",
