  "What your ads cost next to what customers pay you: spend, installs, trials and revenue, with {cac}, {roas}, {ltvCac} and {payback}.": "廣告花費與顧客付給你的金額並列：花費、安裝、試用與營收，以及 {cac}、{roas}、{ltvCac} 和{payback}。",
  "payback": "回本時間",
  "{n} template for this app. Open it, add your words and pictures, and it's made in this style.": "這個 App 有 {n} 個範本。開啟它，加入你的文字和圖片，就會以這個風格做出來。",
  "{n} templates for this app. Open one, add your words and pictures, and it's made in that style.": "這個 App 有 {n} 個範本。開啟其中一個，加入你的文字和圖片，就會以該風格做出來。",
  "A Meta system user token and app secret, in Settings › Your keys": "Meta 系統使用者權杖與應用程式密鑰，位於「設定 › 你的金鑰」",
  "This app's Meta ad account and Facebook Page, in App settings › Connections": "此 App 的 Meta 廣告帳號與 Facebook 粉絲專頁，位於「App 設定 › 連接」",
  "Add both keys in Settings › Your keys. They are checked together once both are saved.": "請在「設定 › 你的金鑰」新增這兩個金鑰。兩者都儲存後會一起檢查。",
