  "Add {key} in Settings > API keys.": "請到「設定 › 你的金鑰」新增{key}。",
  "{provider} refused the key: {reason} Check Settings > API keys.": "{provider} 拒絕了這個金鑰：{reason} 請檢查「設定 › 你的金鑰」。",
  "The AI isn't connected.": "AI 尚未連線。",
  "The AI isn't connected: TypeSafe is the provider chosen in Settings.": "AI 尚未連線：「設定」中選擇的供應商是 TypeSafe。",
  "OpenAI isn't connected.": "OpenAI 尚未連線。",
