  "OpenAI didn't answer in time. Try again in a moment.": "OpenAI 沒有及時回應，請稍後再試一次。",
  "OpenAI's answer wasn't readable. Try again.": "無法讀取 OpenAI 的回覆，請再試一次。",
  "The copy request is too long.": "文案要求的內容太長。",
  "The prompt is too long to improve.": "提示詞太長，無法改善。",
  "OpenAI didn't confirm the search in time. It wasn't sent again, so it isn't paid for twice. The competitors found elsewhere are kept; search again to ask OpenAI once more.": "OpenAI 沒有及時確認這次搜尋。為了避免重複收費，系統沒有再次送出。從其他來源找到的競品都會保留；若要再請 OpenAI 搜尋一次，請重新搜尋。",
  "Apify's monthly credit is used up. Add credit or upgrade at console.apify.com → Billing, then try again.": "Apify 本月的額度已用完。請到 console.apify.com → Billing 加值或升級方案，然後再試一次。",
  "The desktop runner isn't set up yet. Create its secret in Settings > API keys, then give it to the runner.": "桌面執行程式尚未設定。請在「設定 › 你的金鑰」建立它的密鑰，再提供給桌面執行程式。",
  "Sign in first.": "請先登入。",
  "Your session has expired. Sign in again.": "登入狀態已過期，請重新登入。",
  "Confirm your email address first: open the link we sent you, then sign in again.": "請先確認你的電子郵件地址：開啟我們寄給你的連結，然後重新登入。",
  "This account is suspended. Contact support if you think this is a mistake.": "這個帳號已被停用。如果你認為有誤，請聯絡客服。",
  "This account isn't a member of this install. Ask its owner to add you.": "這個帳號不是此工作區的成員。請聯絡擁有者將你加入。",
  "Only the owner of this install can do that.": "只有此工作區的擁有者可以這麼做。",
  "That's a lot of requests in a short time. Wait a few minutes, then try again.": "短時間內的要求太多了。請等幾分鐘後再試一次。",
  "Storage is full: nothing new can be saved. Free up space in Settings > Storage (or upgrade your Supabase plan), then retry.": "儲存空間已滿，無法再儲存新內容。請到「設定 › 儲存空間」釋放空間（或升級 Supabase 方案），然後再試一次。",
  "Your storage is full: nothing new can be saved. Delete rejected or unused creatives, or old saved ad media, in Settings > Storage, then retry.": "你的儲存空間已滿，無法再儲存新內容。請到「設定 › 儲存空間」刪除已退回或未使用的素材，或舊的廣告媒體，然後再試一次。",
  "The file is bigger than your Supabase plan allows ({mb} MB). Make it smaller, or raise the limit on a paid plan.": "檔案超過 Supabase 方案允許的大小（{mb} MB）。請縮小檔案，或改用付費方案提高上限。",
  "This quality takes longer than your Supabase plan allows in one run. Use a lower quality, or upgrade the Supabase plan.": "這個畫質所需的時間超過 Supabase 方案單次執行的上限。請選擇較低的畫質，或升級 Supabase 方案。",
  "This run took too long and was stopped. Try again.": "這次執行花了太久時間，已經停止。請再試一次。",
  "This ad doesn't exist.": "這則廣告不存在。",
  "This project doesn't exist.": "這個專案不存在。",
  "Only {n} review so far: too few to summarize. Refresh the app first, or try one with more reviews.": "目前只有 {n} 則評論，太少了，無法摘要。請先重新整理這個 App，或改試評論較多的 App。",
  "Only {n} reviews so far: too few to summarize. Refresh the app first, or try one with more reviews.": "目前只有 {n} 則評論，太少了，無法摘要。請先重新整理這個 App，或改試評論較多的 App。",
  "This chart came back empty. Try another category or country.": "這個排行榜沒有資料。請換個類別或國家試試。",
  "Add your App Store link first, then its reviews can be read.": "請先新增你的 App Store 連結，才能讀取評論。",
  "Couldn't load the Chinese font (Noto Sans TC) to set this copy. Try again in a moment.": "無法載入排版這段文案所需的中文字型（Noto Sans TC）。請稍後再試一次。",
  "Couldn't load the Japanese font (Noto Sans JP) to set this copy. Try again in a moment.": "無法載入排版這段文案所需的日文字型（Noto Sans JP）。請稍後再試一次。",
  "Couldn't load the Korean font (Noto Sans KR) to set this copy. Try again in a moment.": "無法載入排版這段文案所需的韓文字型（Noto Sans KR）。請稍後再試一次。",
  "This install isn't set up yet. Open /setup to connect a Supabase project.": "此工作區尚未設定。請開啟 /setup 連接 Supabase 專案。",
  "The backend answered {status}. Try again in a moment.": "後端回應了 {status}。請稍後再試一次。",
  "Couldn't reach the backend. Try again in a moment.": "無法連線到後端。請稍後再試一次。",
  "The creatives backend answered {status}.": "素材後端回應了 {status}。",
  "Couldn't reach the creatives backend. Try again in a moment.": "無法連線到素材後端。請稍後再試一次。",
  "The AI reader isn't deployed yet.": "AI 讀取功能尚未部署。",
  "Something went wrong: {detail}": "發生問題：{detail}",
  "Some characters aren't in the built-in font: {chars}. They show as empty boxes: replace them or upload a brand font that has them.": "內建字型沒有這些字元：{chars}。它們會顯示成空白方框：請換個說法，或上傳包含這些字元的品牌字型。",
  // F3 Launch and Measure
  "Everything Launch creates is paused: nothing spends until you publish it in Ads Manager.": "投放建立的一切都是暫停狀態：在廣告管理員發佈之前不會產生任何花費。",
  "Couldn't open Launch": "無法開啟投放",
  "Pick a campaign.": "請選擇一個行銷活動。",
  "That campaign uses an older objective ({objective}) the API can't add to. Pick another or make a new one.": "這個行銷活動使用的是舊版目標（{objective}），API 無法在其中新增廣告。請選擇其他行銷活動或建立新的。",
  "Pick an ad set.": "請選擇一個廣告組合。",
