  "Meta isn't connected": "尚未連結 Meta",
  "Add the Meta system user token and app secret in Settings › Your keys, then this app's ad account and Page in its connections.": "請先在「設定 › 你的金鑰」加入 Meta 系統使用者權杖與應用程式密鑰，再到這個 App 的連結設定中加入廣告帳號與粉絲專頁。",
