  "only approved creatives with a passing QA can be sent": "只有已核准且通過品質檢查的素材才能送出",
  "No approved creatives yet. Approve some in the Studio first.": "還沒有已核准的素材。請先在 Studio 核准素材。",
  "Format": "格式",
  "{n} single ads": "{n} 則單一廣告",
  "Single image or video": "單一圖片或影片",
  "One ad, a version per placement": "一則廣告，各版位一個版本",
  "Each creative becomes its own ad, so Meta can find the winner. Videos use Meta's thumbnail (or the creative's cover).": "每個素材各自成為一則廣告，讓 Meta 找出勝出的素材。影片會使用 Meta 的縮圖（或素材的封面）。",
  "One ad with 2–10 cards people swipe through, each with its own headline and link. Good for showing several features.": "一則廣告包含 2–10 張可滑動瀏覽的卡片，每張都有自己的標題與連結。適合展示多項功能。",
  "One ad, with the best-fitting version in each placement: for example a 4:5 for feeds and a 9:16 for Stories and Reels. Exactly one version is the fallback.": "一則廣告在各版位顯示最適合的版本：例如動態消息用 4:5，限時動態與 Reels 用 9:16。其中恰好一個版本作為備用。",
  "Pick two or more creatives for a carousel or placement versions.": "選擇兩個以上的素材，即可製作輪播或各版位版本。",
