  "Where disclaimers go (from the creative's copy). Instagram and single-media Facebook Feed ads don't show it.": "放置免責聲明的地方（來自素材的文案）。Instagram 與單一素材的 Facebook 動態消息廣告不會顯示。",
  "Made with AI?": "是否以 AI 製作？",
  "Meta asks advertisers to say whether the media was made or edited with AI; it may then show an “AI info” label where the law asks for it (the EU, India, Taiwan, California, New York).": "Meta 要求廣告主聲明素材是否以 AI 製作或編輯；在法律要求的地區（歐盟、印度、台灣、加州、紐約），可能會顯示「AI 資訊」標籤。",
  "Yes, made or edited with AI": "是，以 AI 製作或編輯",
  "Preselected: a picked creative was made by a model (AI people or a generated scene).": "已預先選取：所選素材中有由模型製作的內容（AI 人物或生成的場景）。",
  "Creatives made in the Studio are AI-generated, so this is usually the answer.": "在 Studio 製作的素材都是 AI 生成的，所以通常選這個。",
  "No AI in this media": "這個素材沒有使用 AI",
  "Display link": "顯示連結",
  "A short domain shown on the ad, like acme.app. Not the destination.": "顯示在廣告上的簡短網域，例如 acme.app。不是實際的目的地。",
  "URL parameters": "網址參數",
  "Advantage+ creative": "Advantage+ 素材",
  "Lets Meta touch up the media and rewrite text per person (brightness, animation, text variations). Off keeps each ad exactly as approved.": "讓 Meta 針對每個人微調素材並改寫文字（亮度、動畫、文字變化）。關閉則讓每則廣告維持核准時的樣子。",
  "Optional tags added to the link.": "加在連結上的選用標記。",
  "Empty: Launch adds UTM tags with the campaign, ad set and ad names, so analytics see the naming convention.": "留空時：投放會加上含行銷活動、廣告組合與廣告名稱的 UTM 標記，讓分析工具也能看到命名規則。",
  "Everywhere else (fallback)": "其他所有位置（備用）",
  "Feeds (4:5 or 1:1)": "動態消息（4:5 或 1:1）",
  "Stories and Reels (9:16)": "限時動態與 Reels（9:16）",
  "{n} picked": "已選 {n} 個",
  "Pixel from Launch settings": "投放設定中的像素",
  "Follows the naming convention; it updates with the places you pick unless you rename it.": "依照命名規則；除非你手動改名，否則會隨你選的地區更新。",
  "Optimise for": "最佳化目標",
  "{name} (default)": "{name}（預設）",
  "The playbook: optimise for the deepest event that still happens often (a trial or purchase over an install), so Meta learns who pays.": "實戰原則：針對仍經常發生的最深層事件做最佳化（試用或購買優於安裝），讓 Meta 學會誰會付費。",
  "Meta app {id}": "Meta 應用程式 {id}",
  "Add the Meta app id in Launch settings.": "請在投放設定中加入 Meta 應用程式 ID。",
  "App event": "應用程式事件",
  "Sent by the Meta SDK (or your MMP) from the app.": "由 App 中的 Meta SDK（或你的 MMP）傳送。",
  "Pixel": "像素",
  "The website's Meta pixel (or dataset).": "網站的 Meta 像素（或資料集）。",
  "Connect a pixel in Launch settings: this goal needs one.": "請在投放設定中連結像素：這個目標需要像素。",
  "Custom conversions": "自訂轉換",
  "Event": "事件",
  "Send people to": "將使用者導向",
  "Budget": "預算",
  "This campaign gives each ad set its own budget (ABO).": "這個行銷活動為每個廣告組合分別設定預算（ABO）。",
  "Lifetime budget": "總經費",
  "Testing: about $20–50 a day per ad set, with about 5 ads in it.": "測試：每個廣告組合每天約 $20–50，內含約 5 則廣告。",
  "Raise winners about 20% every 48 h.": "每 48 小時將勝出者的預算提高約 20%。",
