  "Ends": "結束",
  "A lifetime budget needs an end date.": "總經費需要設定結束日期。",
  "The campaign holds the budget and the bid strategy (CBO), so this ad set has none of its own.": "預算與出價策略都設在行銷活動上（CBO），所以這個廣告組合沒有自己的設定。",
  "Who sees the ads": "誰會看到廣告",
  "Broad targeting usually wins: the creative tells Meta who it's for.": "廣泛目標設定通常效果最好：素材本身就會告訴 Meta 適合哪些人。",
