  "Advantage+ audience": "Advantage+ 受眾",
  "On: the ages and interests below are suggestions. Meta may show the ads to people outside them when it expects better results.": "開啟：下方的年齡與興趣只是建議。當 Meta 預期成效更好時，可能會將廣告顯示給範圍以外的人。",
  "Off: the ages and interests below are hard limits.": "關閉：下方的年齡與興趣是硬性限制。",
