  "Interests": "興趣",
  "Optional. Only from Meta's search, so every interest is real. Most tests run without any.": "選填。只能從 Meta 的搜尋結果中選，所以每個興趣都是真實存在的。大多數測試都不設定興趣。",
  "Search interests (fitness, cooking…)": "搜尋興趣（健身、烹飪…）",
  "Estimating the audience…": "正在估算受眾…",
  "About {low}–{high} people a month (Meta's estimate).": "每月約 {low}–{high} 人（Meta 估算）。",
  "Meta's audience estimate shows here.": "Meta 的受眾估算會顯示在這裡。",
  "Where the ads show": "廣告顯示位置",
  "Advantage+ placements": "Advantage+ 版位",
  "Pick placements": "手動選擇版位",
  "Meta shows the ads wherever they'll do best: Feeds, Stories, Reels and more. Recommended.": "Meta 會在成效最好的地方顯示廣告：動態消息、限時動態、Reels 等。建議使用。",
  "Only where you pick. Fewer places usually costs more per result.": "只在你選的位置顯示。位置越少，單次成果的成本通常越高。",
  "EU transparency (Digital Services Act)": "歐盟透明度要求（數位服務法）",
  "Ads shown in the EU name who benefits from them and who pays for them.": "在歐盟顯示的廣告必須標明受益者與付款者。",
  "Who benefits": "受益者",
  "Who pays": "付款者",
