  "Showings": "顯示次數",
  "Days": "天數",
  "Attribution window": "歸因期間",
  "How long after a click or view a result counts. Meta's default (7-day click, 1-day view) suits most accounts.": "點擊或瀏覽後多久內的成果會被計入。Meta 的預設值（點擊後 7 天、瀏覽後 1 天）適合大多數帳號。",
  "Meta’s default (7-day click, 1-day view)": "Meta 預設（點擊後 7 天、瀏覽後 1 天）",
  "7-day click": "點擊後 7 天",
  "1-day click": "點擊後 1 天",
