  "Custom audiences": "自訂受眾",
  "People from your website, app or a lookalike. With Advantage+ audience on, these are suggestions too.": "來自你的網站、App 或類似受眾的人。開啟 Advantage+ 受眾時，這些也只是建議。",
  "Include an audience…": "加入受眾…",
