  "Languages": "語言",
  "Only people who use Facebook or Instagram in these languages. Usually left empty.": "只限以這些語言使用 Facebook 或 Instagram 的人。通常留空。",
  "Add a language": "新增語言",
  "Targeting an EU country adds the Digital Services Act fields (who benefits, who pays).": "目標設定包含歐盟國家時，會加入數位服務法的欄位（受益者、付款者）。",
  "This campaign has a special ad category: targeting must stay 18–65, all genders.": "這個行銷活動屬於特殊廣告類別：目標設定必須維持 18–65 歲、所有性別。",
