  "App installs": "應用程式安裝",
  "Follows the naming convention so Measure can group results; change it if you like.": "依照命名規則，讓衡量能分組彙整成果；需要的話可以修改。",
  "Objective": "目標",
  "Where the money is set decides who moves it between ad sets.": "預算設在哪裡，決定由誰在廣告組合之間調度預算。",
  "On each ad set (ABO)": "設在各廣告組合（ABO）",
  "You give every ad set its own budget, so each new concept gets a fair test. The playbook's choice for testing.": "你為每個廣告組合分別設定預算，讓每個新概念都得到公平的測試。實戰原則中測試時的選擇。",
  "On the campaign (CBO)": "設在行銷活動（CBO）",
  "One budget; Meta moves it to the ad sets doing best. The playbook's choice for scaling winners.": "一份預算，由 Meta 移到表現最好的廣告組合。實戰原則中擴量勝出者時的選擇。",
  "Testing usually runs ABO, so every concept gets spend. CBO is for scaling proven winners.": "測試通常使用 ABO，讓每個概念都有花費。CBO 用於擴量已證實的勝出者。",
  "Spent over the campaign's dates; needs an end date.": "在行銷活動期間內花完；需要結束日期。",
  "Meta may spend a little more on good days and less on others.": "Meta 可能在成效好的日子多花一點，其他日子少花一點。",
  "Campaign budget": "行銷活動預算",
  "Meta asks for the cap or ROAS floor on each ad set of a CBO campaign; set those in Ads Manager before publishing.": "Meta 要求在 CBO 行銷活動的每個廣告組合上設定上限或 ROAS 下限；請在發佈前到廣告管理員設定。",
  "A lifetime budget needs an end date (More options).": "總經費需要結束日期（更多選項）。",
  "Spending limit": "花費上限",
  "The most this campaign may ever spend, whatever the budgets say. Optional.": "不論預算設定如何，這個行銷活動最多能花費的金額。選填。",
  "No limit": "無上限",
  "Special ad category": "特殊廣告類別",
  "Only for ads about housing, jobs, credit or politics: Meta then limits targeting by age, gender and place.": "僅適用於住房、就業、信貸或政治相關的廣告：Meta 會限制依年齡、性別與地區的目標設定。",
  "None": "無",
  "Countries for the category": "適用此類別的國家",
  "Two-letter codes, comma separated (US, GB).": "兩個字母的代碼，以逗號分隔（US, GB）。",
  "SKAdNetwork attribution": "SKAdNetwork 歸因",
  "Apple’s privacy-safe install counting for iOS apps. Leave on for iOS.": "Apple 為 iOS App 提供、兼顧隱私的安裝計算方式。iOS 請保持開啟。",
