  "Create {n} paused draft on Meta?": "要在 Meta 上建立 {n} 個暫停的草稿嗎？",
  "Create {n} paused drafts on Meta?": "要在 Meta 上建立 {n} 個暫停的草稿嗎？",
  "{n} selected · goes to the testing ad set, paused": "已選 {n} 個 · 將以暫停狀態進入測試廣告組合",
