  "Nothing launched yet": "還沒有投放任何廣告",
  "Pick approved creatives above and launch them: they arrive here as paused drafts.": "在上方選擇已核准的素材並投放，它們會以暫停的草稿出現在這裡。",
  "testing": "測試",
