  "Show all {n}": "顯示全部 {n} 個",
  "Paused draft": "暫停的草稿",
  "daily upload": "每日上傳",
  "promoted": "已升級",
  "Likely CAC": "可能的 CAC",
  "Meta duplicates the ad into the scaling ad set, paused, named with SCALE. The testing ad keeps running until you pause it.": "Meta 會把廣告複製到擴量廣告組合（暫停狀態，名稱含 SCALE）。測試中的廣告會持續投放，直到你暫停它。",
  "From {since} to {until}, judged on {events} against a {target} target CAC.": "{since} 至 {until}，依{events}判斷，目標 CAC 為 {target}。",
  "From {since} to {until}, judged on {events}.": "{since} 至 {until}，依{events}判斷。",
  "Only actionable": "只看需處理的",
  "All {n} ads": "全部 {n} 則廣告",
  "No target CAC yet": "尚未設定目標 CAC",
  "Set a target CAC in Launch settings to get promote and pause suggestions.": "在投放設定中設定目標 CAC，即可取得升級與暫停建議。",
  "Open Launch settings": "開啟投放設定",
  "No numbers yet": "還沒有數據",
  "Keep testing": "繼續測試",
  "Couldn't save.": "無法儲存。",
  "Account warm-up": "帳號暖身",
  "done": "已完成",
  "skipped (the account has history)": "已略過（帳號已有紀錄）",
  "Undo": "復原",
  "Warm up the ad account": "為廣告帳號暖身",
  "optional": "選填",
  "no spend in 28 days": "28 天內沒有花費",
  "day {day} of {min}–{max}": "第 {day} 天（共 {min}–{max} 天）",
  "Meta knows nothing about a fresh account. A few days of healthy engagement first gives conversion ads a cleaner start (fewer rejections, steadier delivery). It won't make a weak ad profitable; it just starts on the right foot.": "Meta 對全新的帳號一無所知。先累積幾天良好的互動，能讓轉換廣告起步更順（較少被拒、投放更穩定）。這不會讓表現差的廣告變得獲利，只是讓你有個好的開始。",
  "Create an {engagement} campaign in Ads Manager. Sell nothing.": "在廣告管理員建立一個{engagement}行銷活動，不要銷售任何東西。",
  "Engagement": "互動",
  "Use simple static images people like to react to (puppies, babies). A small budget is plenty: about $37 bought ~2,400 engagements at $0.02 in the playbook's example.": "使用大家喜歡按讚的簡單靜態圖片（小狗、寶寶）。小預算就足夠：在教戰手冊的範例中，約 $37 換到約 2,400 次互動，每次 $0.02。",
  "Let it run {min}–{max} days. Avoid switching things on and off or big edits meanwhile.": "讓它投放 {min}–{max} 天，期間避免反覆開關或大幅修改。",
  "Then publish the app drafts from Launch and optimise for the conversion you care about.": "接著發佈從投放建立的應用程式草稿，並針對你在意的轉換進行最佳化。",
  "I've started the warm-up": "我已開始暖身",
  "Mark warmed up": "標示為已暖身",
  "Open Ads Manager ↗": "開啟廣告管理員 ↗",
  "Skip, the account has history": "略過，帳號已有紀錄",
  "Attribution: SDK first, MMP later": "歸因：先用 SDK，之後再用 MMP",
  "Not SDK or MMP: the SDK gets campaigns learning now; the MMP gives better attribution once it has data. Starting on the MMP from day one usually starves learning.": "不是 SDK 和 MMP 二選一：SDK 讓行銷活動現在就開始學習；MMP 累積資料後能提供更好的歸因。第一天就只靠 MMP，通常會讓學習缺乏資料。",
  "AppStack connected": "AppStack 已連接",
  "no MMP connected": "未連接 MMP",
  "{n} {events} in 7 days": "7 天內 {n} 次{events}",
  "About 50 a week is enough.": "每週約 50 次就足夠。",
  "I'm here": "我在這一步",
  "You have enough volume to move the optimisation events to the MMP.": "你的量已足夠，可以把最佳化事件改由 MMP 提供。",
  "Advice for the scaling ad set from the playbook. Budgets are changed by you in Ads Manager; nothing here changes them.": "根據教戰手冊給擴量廣告組合的建議。預算由你在廣告管理員中調整，這裡不會更改任何預算。",
  "Last 3 days": "最近 3 天",
  "{n} {events}": "{n} 次{events}",
  "Cost per {event}, last 3 days": "每次{event}成本（最近 3 天）",
  "The 4 days before": "再之前的 4 天",
  "About 20% every 48 hours while it holds; judge where the cost settles, not the next morning.": "只要表現穩定，每 48 小時調高約 20%；看成本最後穩定在哪裡，而不是隔天早上的數字。",
  "Open the scaling ad set ↗": "開啟擴量廣告組合 ↗",
  "Playbook": "教戰手冊",
  "Suggestions from the Meta ads playbook. Optional: skip or mark anything done.": "來自 Meta 廣告教戰手冊的建議。皆為選用：可略過或標示為已完成。",
  "Meta SDK with your key events": "Meta SDK 搭配你的關鍵事件",
  "Install, trial start and purchase sent from the app through Meta's SDK (or Pixel + Conversions API on the web). Run SDK-optimised campaigns straight away.": "透過 Meta 的 SDK（網站則用像素 + Conversions API）從應用程式傳送安裝、開始試用與購買事件。立刻就能投放以 SDK 最佳化的行銷活動。",
  "MMP collecting alongside": "MMP 同步收集資料",
  "Connect the MMP (AppStack here) while the SDK campaigns run, so it builds conversion history.": "在 SDK 行銷活動投放期間連接 MMP（這裡是 AppStack），讓它累積轉換紀錄。",
  "Switch events to the MMP": "把事件切換到 MMP",
  "Once the MMP has enough conversions, set the app's events to come from it in Ads Manager (the app's integrations) and optimise on them.": "MMP 累積足夠的轉換後，在廣告管理員（應用程式的整合設定）中把事件來源設為 MMP，並以這些事件進行最佳化。",
  "Set up": "設定",
