  "Where ads go, the testing and scaling ad sets, and the promotion rules.": "廣告的去向、測試與擴量廣告組合，以及升級規則。",
  "Not saved yet: these are the defaults. Fill in the Meta ids and save.": "尚未儲存：目前是預設值。請填入 Meta ID 後儲存。",
