  "Countries": "國家",
  "Two-letter codes, comma separated.": "兩個字母的代碼，以逗號分隔。",
  "Short code for names": "名稱用的簡短代碼",
  "Starts every name: ACME | TEST | format | hook | v01 | date": "放在每個名稱的開頭：ACME | TEST | 格式 | 開場鉤子 | v01 | 日期",
