  "Follows of your Facebook Page.": "追蹤你的 Facebook 粉絲專頁。",
  "Leads (instant form)": "潛在顧客（即時表單）",
  "A form inside Facebook or Instagram.": "Facebook 或 Instagram 內的表單。",
