  "Meta gets as many results as the budget allows. The playbook's default.": "Meta 會在預算允許內取得最多成果。教戰手冊的預設。",
  "Keeps the average cost per result near an amount you set.": "讓平均單次成果成本維持在你設定的金額附近。",
