  "Fill in the fields below, or import a brand guide you already have (paste it, or pick a file). Until then, creatives use what's below and the AI product profile.": "填寫下方欄位，或匯入你現有的品牌指南（貼上內容或選擇檔案）。在那之前，素材會使用下方內容和 AI 產品簡介。",
  "It didn't upload.": "沒有上傳成功。",
  "It's removed from this product and its file is deleted. This can't be undone.": "它會從這個產品中移除，檔案也會刪除。此動作無法復原。",
  "It's removed from this product. To keep it but leave it out of suggestions, hide it instead.": "它會從這個產品中移除。若想保留但不出現在建議中，請改用隱藏。",
  "Kind picked by you: the AI won't change it": "類型由你選定：AI 不會更改",
  "OpenAI didn't answer. Try again.": "OpenAI 沒有回應，請再試一次。",
  "Optional. Names, @handles or links, separated by commas. Don't know any yet? That's what {app} is for: leave it empty.": "選填。輸入名稱、@帳號或連結，以逗號分隔。還不知道有哪些競品？{app} 就是為此而生，留空即可。",
  "QA checks {n} forbidden claim, plus the AI profile's claims to avoid.": "QA 會檢查 {n} 項禁止的宣稱，以及 AI 簡介列出的應避免宣稱。",
  "QA checks {n} forbidden claims, plus the AI profile's claims to avoid.": "QA 會檢查 {n} 項禁止的宣稱，以及 AI 簡介列出的應避免宣稱。",
  "Store listing, docs, anything about it. One per line. After you save, the AI reads them and your website's pages, then offers a fuller profile: the problem, the customer, your brand colours and voice.": "商店頁面、文件，任何相關資料都可以，一行一個。儲存後，AI 會讀取這些連結和你網站的頁面，提供更完整的簡介：問題、顧客、品牌顏色與語氣。",
  "Suggestions for colours, voice and claims to avoid come from the AI's read of your links. It needs {keys}.": "顏色、語氣和應避免宣稱的建議，來自 AI 對你連結的解讀。需要：{keys}。",
  "That file isn't in this product's folder.": "這個檔案不在此產品的資料夾中。",
  "The AI reads your link and your website's pages, then writes a fuller profile: the problem, the customer, value, pricing, proof, your brand colours and voice.": "AI 會讀取你的連結和網站頁面，寫出更完整的簡介：問題、顧客、價值、定價、佐證、品牌顏色與語氣。",
  "The AI reads your {n} links and your website's pages, then writes a fuller profile: the problem, the customer, value, pricing, proof, your brand colours and voice.": "AI 會讀取你的 {n} 個連結和網站頁面，寫出更完整的簡介：問題、顧客、價值、定價、佐證、品牌顏色與語氣。",
  "The app couldn't be deleted: {reason}. Try again in a moment.": "無法刪除這個 App：{reason}。請稍後再試。",
  "The app's files couldn't be removed, so the app wasn't deleted. {reason}": "無法移除這個 App 的檔案，因此 App 沒有被刪除。{reason}",
  "The change wasn't saved.": "變更沒有儲存。",
