  "The image was uploaded but couldn't be saved. Try again.": "圖片已上傳，但無法儲存，請再試一次。",
  "The numbers a creative may show (a rating, a count, a comparison price), word for word. QA fails any other number that isn't an offer's wording.": "素材可以顯示的數字（評分、數量、比較價格），必須逐字相同。若出現其他不是優惠文字的數字，QA 會判定不通過。",
  "There's no AI profile yet: read your links first.": "還沒有 AI 簡介：請先讀取你的連結。",
  "These fields get the AI profile's version. You can undo it afterwards.": "這些欄位會換成 AI 簡介的版本，之後可以復原。",
  "They didn't agree: don't use them.": "對方未同意：請勿使用。",
