  "This app doesn't exist.": "這個 App 不存在。",
  "This is the product's one competitor list, the same one as Research → Competitors. Ones you follow there or that have a Facebook Page are removed there.": "這是產品唯一的競品清單，和「研究 → 競品」是同一份。已追蹤或有 Facebook 粉絲專頁的競品，請到那裡移除。",
  "Use a TTF, OTF or WOFF font file (WOFF2 can't be rendered).": "請使用 TTF、OTF 或 WOFF 字型檔（WOFF2 無法算繪）。",
  "We don't offer": "我們不提供",
  "We've filled in what we could from your description; fix anything that's off.": "我們已根據你的描述盡量填好，有不對的地方請修正。",
  "What Meta's link description carries on every ad (written copy starts with these). Keep results disclaimers here, not on the image.": "每則廣告的 Meta 連結說明都會帶上這些內容（文案會以它們開頭）。效果相關的免責聲明放在這裡，不要放在圖片上。",
  "What it is, who it's for and how people buy it, in a few honest lines.": "用幾句誠實的話說明：它是什麼、為誰而做、大家怎麼購買。",
  "What you sell, as pictures. They are suggested as references when you recreate a competitor's ad.": "用圖片呈現你賣的東西。重製競品的廣告時，這些圖片會被建議作為參考。",
  "What you're building": "你在打造什麼",
