  "No App Store reviews saved for this product yet. They're read with your App Store link.": "這個產品還沒有儲存任何 App Store 評論。評論會透過你的 App Store 連結讀取。",
  "Prices from Higgsfield's cost check on {date}; the live price is checked again before it runs.": "價格來自 Higgsfield {date} 的費用查詢；執行前會再確認一次即時價格。",
