  "This product already has {n} of your own templates. Delete one first.": "這個產品已經有 {n} 個你自己的範本，請先刪除一個。",
  "This product already has {n} uploaded templates. Delete one first.": "這個產品已經有 {n} 個上傳的範本，請先刪除一個。",
  "Use a PNG, JPEG or WebP image.": "請使用 PNG、JPEG 或 WebP 圖片。",
  "Built for {fits}; {name} is a physical product.": "這是為{fits}設計的；{name} 是實體商品。",
  "Built for {fits}; {name} is a service.": "這是為{fits}設計的；{name} 是服務。",
  "Built for {fits}; {name} is an app.": "這是為{fits}設計的；{name} 是 App。",
  "Keep the image under 10 MB.": "圖片請小於 10 MB。",
  "Keep the name under {max} characters.": "名稱請少於 {max} 個字元。",
  "Starters are ready as they are.": "入門範本可以直接使用。",
  "This product's Library is empty": "這個產品的範本庫是空的",
  "Adds your brand's look, name and rules. Off: the prompt goes as written.": "加入品牌的風格、名稱與規則。關閉時：提示詞照原樣送出。",
  "Couldn't delete the result. Try again.": "無法刪除這個結果，請再試一次。",
  "Couldn't do that. Try again.": "無法執行，請再試一次。",
  "Couldn't start the upload: {message}": "無法開始上傳：{message}",
  "Couldn't take a frame from the video.": "無法從影片擷取畫面。",
  "Couldn't upload the image. Try again.": "無法上傳圖片，請再試一次。",
  "If the camera is a phone propped up, describe the camera position ('low static camera on the counter, looking up') rather than saying 'phone' — otherwise the model may also draw a phone in the scene.": "如果是用架起來的手機拍攝，請描述鏡頭位置（例如「放在檯面上的低角度固定鏡頭，向上拍」），不要寫「手機」，否則模型可能會把手機也畫進畫面。",
  "It's still being made: cancel its queued jobs first.": "仍在製作中：請先取消排隊中的工作。",
  "Made by OpenAI's Images API with this product's server key, billed by OpenAI in dollars (no Higgsfield credits). Estimated from OpenAI's published prices, checked {date}; reference images add an estimated input cost. Results are saved to this product's storage and checked like any other.": "使用此產品的伺服器金鑰，透過 OpenAI 的 Images API 製作，由 OpenAI 以美元計費（不使用 Higgsfield 點數）。費用依 OpenAI 公布的價格估算（{date} 確認）；參考圖片會增加估算的輸入費用。結果會存到此產品的儲存空間，並和其他素材一樣接受檢查。",
  "Pause on the frame you want: it's added to the form as an image": "停在你要的畫面：它會以圖片加入表單",
  "Prices from Higgsfield's cost check on {date}. Each job's live price is checked again before it runs, and one that costs much more is refused. Results are saved to this product's storage.": "價格來自 Higgsfield 於 {date} 的費用檢查。每個工作執行前都會再確認即時價格，貴很多的會被拒絕。結果會存到此產品的儲存空間。",
  "Product shots, app screens, a logo: they stand in for the reference's product and brand.": "產品照、App 畫面、標誌：它們會取代參考圖中的產品與品牌。",
  "That's the limit": "已達上限",
  "The creative studio's tables aren't in the database yet (migration 20261002500000).": "資料庫中還沒有素材工作室的資料表（遷移 20261002500000）。",
  "The example is another brand's ad, used only for its layout. Its brand is replaced with yours and kept out of the result.": "範例是其他品牌的廣告，只用來參考版面。它的品牌會換成你的，也不會出現在結果中。",
  "The image is deleted from this product's storage and leaves Launch, where it's approved. This can't be undone.": "圖片會從此產品的儲存空間刪除，也會從已核准的「投放」中移除。此動作無法復原。",
  "The image is deleted from this product's storage. This can't be undone.": "圖片會從此產品的儲存空間刪除。此動作無法復原。",
  "The model's safety filter blocked this (often a false positive). Try: name a setting other than 'bathroom' (e.g. vanity sink, skincare routine), say the person is fully dressed, frame from the shoulders up, avoid words like 'dripping', 'leans over', 'body'.": "模型的安全過濾器擋下了這個（常常是誤判）。試試：場景不要寫「浴室」（例如改成梳妝台洗手台、保養流程），註明人物衣著完整，取景從肩膀以上，避免「dripping」、「leans over」、「body」這類字眼。",
  "This generation doesn't exist.": "找不到這次生成。",
  "This product doesn't exist.": "找不到這個產品。",
  "This result doesn't exist.": "找不到這個結果。",
  "What it's for": "適合用途",
  "With only a start frame, the Higgsfield API makes the video in that image's shape (the aspect is used on the desktop runner).": "只有起始畫面時，Higgsfield API 會依該圖片的比例製作影片（桌面執行程式才會套用所選比例）。",
  "With {n} images it runs on Higgsfield's API (the desktop runner sends at most {max}).": "有 {n} 張圖片時，會在 Higgsfield 的 API 上執行（桌面執行程式最多送出 {max} 張）。",
  "Your text names {names}. Ads that name competitors are often rejected; it's kept as you wrote it.": "你的文字提到了 {names}。點名競品的廣告常會被拒登；文字會照你寫的保留。",
  "{provider}'s safety filter blocked this (sometimes a false positive). Rephrase the prompt (plainer wording, no real brands, people or claims it could read as harmful) or change the images.": "{provider} 的安全過濾器擋下了這個（有時是誤判）。請改寫提示詞（用更平實的說法，不要出現真實品牌、人物，或可能被視為有害的宣稱），或更換圖片。",
  "(voices, ambience)": "（人聲、環境音）",
  "1 reference": "1 張參考圖",
  "2 versions · {aspect} · nothing is generated until you confirm in Remix.": "2 個版本 · {aspect} · 在混搭中確認前不會生成任何內容。",
  "4:5 (made in 3:4)": "4:5（以 3:4 製作）",
