  "Puts this request back in the form on the other provider (same model, GPT Image 2.5); nothing is spent until you generate and confirm the price": "把這個請求放回表單並改用另一個供應商（同樣是 GPT Image 2.5 模型）；在你生成並確認價格前不會花費任何費用",
