  "Reddit-style post": "Reddit 風格貼文",
  "Tweet-style post": "推文風格貼文",
  "A presenter, phone-filmed feel": "有出鏡人物，手機拍攝感",
  "How-to": "教學",
  "A presenter shows how it works": "出鏡人物示範如何使用",
  "Product review": "產品評測",
  "A presenter's take on the app": "出鏡人物分享對 App 的看法",
  "Unboxing": "開箱",
  "A first-look reveal": "初次揭曉",
