  "Couldn't place the logo. Try again.": "無法放上標誌，請再試一次。",
  "Couldn't queue it for {provider}. Try again.": "無法排入 {provider} 的佇列，請再試一次。",
  "Couldn't queue it. Try again.": "無法排入佇列，請再試一次。",
  "Couldn't queue the job. Try again.": "無法將工作排入佇列，請再試一次。",
