  "Couldn't store the image. Try again.": "無法儲存圖片，請再試一次。",
  "Couldn't store {file}. Try again.": "無法儲存 {file}，請再試一次。",
  "Couldn't switch the copy. Try again.": "無法切換文案，請再試一次。",
  "Couldn't take the logo off: {reason}": "無法移除標誌：{reason}",
  "Couldn't write the copy": "無法撰寫文案",
