  "Into this app's Drive folder, in the same folders as the zip": "放進這個 App 的 Drive 資料夾，資料夾結構與 ZIP 檔相同",
  "It's already running; it can't be stopped halfway (Higgsfield charges once it starts).": "已經在執行中，無法中途停止（Higgsfield 一開始就會計費）。",
  "Our logo isn't placed on this ad yet. Wait for it, or try again.": "這則廣告還沒放上我們的標誌。請稍候，或再試一次。",
  "Our logo wasn't placed": "我們的標誌沒有放上去",
  "Our logo wasn't placed: {reason}": "我們的標誌沒有放上去：{reason}",
  "QA raised warnings: add a note saying why it's fine to ship.": "檢查提出了警告：請加上備註，說明為什麼仍可以上線。",
  "The AI writes two versions of each: A in a creator's voice, B in the brand's, following your brand rules. Version A becomes the ad copy, and it is checked again.": "AI 會依照你的品牌規則為每個素材寫兩個版本：A 用創作者口吻，B 用品牌口吻。A 版會成為廣告文案，並再次接受檢查。",
  "The check failed: fix the brief and make a new one. Failed creatives can't be approved.": "檢查未通過：請修改簡報後重新製作。未通過的素材無法核准。",
  "The check raised a warning: say why it's fine to ship (required to approve).": "檢查提出了警告：請說明為什麼仍可以上線（核准時必填）。",
  "The copy couldn't be written. Try again.": "無法撰寫文案，請再試一次。",
  "The copy was written but couldn't be saved. Try again.": "文案已寫好，但無法儲存，請再試一次。",
  "The text didn't fit the layout: edit it (Edit text) before approving.": "文字放不進版面：請先編輯（編輯文字）再核准。",
  "The text isn't set on this ad yet. Wait for it, or try again.": "這則廣告還沒放上文字。請稍候，或再試一次。",
  "The text wasn't set": "文字沒有放上去",
