  "Storage refused the upload. Open /setup and press Apply the update, then try again.": "儲存空間拒絕了上傳。請開啟 /setup 並按「套用更新」，然後再試一次。",
  "Text read on the creative ({n} line)": "從素材讀到的文字（{n} 行）",
  "Text read on the creative ({n} lines)": "從素材讀到的文字（{n} 行）",
  "The check reads the creative, not this copy: keep it to the same rules (no guarantees, no personal attributes).": "檢查只會讀取素材本身，不會讀這段文案：請遵守相同的規則（不保證效果、不提及個人特徵）。",
  "The estimate changed to {price}; check it and confirm again.": "預估費用已變為 {price}，請確認後再次確認。",
