  "The finished file is still at the provider (links may expire):": "完成的檔案還在供應商那裡（連結可能會失效）：",
  "The same prompt and images, on the same provider. A job that failed before it was charged costs the same again.": "相同的提示詞與圖片，相同的供應商。在收費前就失敗的工作，重試仍會收取相同費用。",
  "The same prompt and images, the same model, on the other provider. It joins this batch as a new job; the failed one stays as it is.": "相同的提示詞、圖片與模型，改由另一個供應商製作。它會以新工作加入這個批次，失敗的工作維持原樣。",
  "This video has no poster frame, which Launch needs. Make it again.": "這支影片沒有封面影格，而投放需要它。請重新製作。",
  "To review": "待審核",
