  "The posts were rendered, but the creatives backend didn't confirm them ({reason}), so they aren't checked yet. If they stay queued, start the batch again.": "貼文已產生，但素材後端沒有確認（{reason}），所以尚未檢查。如果一直停在排隊中，請重新開始這批。",
