  "Where Launch creates paused drafts and Measure reads spend and installs.": "投放會在這裡建立暫停的草稿，衡量會從這裡讀取花費和安裝數。",
  "Ad account ID": "廣告帳號 ID",
  "Ads Manager → account dropdown. With or without act_.": "廣告管理員 → 帳號下拉選單。可含或不含 act_。",
  "Facebook Page ID": "Facebook 粉絲專頁 ID",
  "Page → About → Page transparency, or Business settings → Pages.": "粉絲專頁 → 關於 → 粉絲專頁資訊透明度，或企業管理設定 → 粉絲專頁。",
  "Instagram account ID": "Instagram 帳號 ID",
  "Business settings → Instagram accounts. The numeric ID, not the handle.": "企業管理設定 → Instagram 帳號。請填數字 ID，不是帳號名稱。",
  "Pixel / dataset ID": "像素 / 資料集 ID",
  "Events Manager → Data sources → your dataset → Settings tab → Dataset ID.": "事件管理工具 → 資料來源 → 你的資料集 → 設定分頁 → 資料集 ID。",
  "Meta app ID": "Meta 應用程式 ID",
  "developers.facebook.com → your app. Needed for app install campaigns.": "developers.facebook.com → 你的應用程式。應用程式安裝行銷活動需要它。",
  "Trials, subscriptions and revenue, so Measure can work out LTV and payback.": "試用、訂閱和營收，讓衡量可以算出 LTV 和回本時間。",
  "Project settings › General, starts with proj. A link from the dashboard works too.": "Project settings › General，以 proj 開頭。也可以貼上控制台的連結。",
  "Install attribution from the App Store, matched to campaigns.": "來自 App Store 的安裝歸因，並對應到行銷活動。",
  "App ID": "App ID",
  "Your app's bundle ID (iOS) or package name (Android).": "你 App 的 bundle ID（iOS）或套件名稱（Android）。",
  "Where this product's files go: brand assets, generated creatives, exports.": "這個產品的檔案存放位置：品牌素材、生成的素材和匯出檔。",
  "Supabase Storage folder": "Supabase Storage 資料夾",
  "Bucket, then folder. Leave empty for the default.": "先填儲存桶，再填資料夾。留空則使用預設值。",
  "Google Drive folder ID (optional)": "Google Drive 資料夾 ID（選填）",
  "Paste the folder link or its ID. For sharing finished creatives.": "貼上資料夾連結或 ID，用來分享完成的素材。",
  "Name, icon, screenshots, look, voice, offers and the claims a creative must never make: every creative follows it.": "名稱、圖示、截圖、外觀、語氣、優惠，以及素材絕不能做出的宣稱：每個素材都遵循它。",
  "Your competitors' paid ads from Meta's Ad Library: what's running, for how long, and why it works.": "來自 Meta 廣告檔案庫的競品付費廣告：正在投放什麼、投放多久，以及為什麼有效。",
  "Your competitors' apps on the App Store: ratings, prices, how often they ship, what reviewers love and hate, and the top charts.": "App Store 上的競品 App：評分、價格、更新頻率、評論者喜歡和討厭的地方，以及排行榜。",
  "A library of proven ad formats, each with a recreate prompt ready for the Studio (now the Studio's Start from).": "已驗證的廣告格式庫，每個格式都附有可直接用於 Studio 的重製提示詞（現為 Studio 的「從這裡開始」）。",
  "Make creatives from a format and the brand, then check them against the forbidden claims before they go anywhere.": "依格式和品牌製作素材，並在送出前對照禁止宣稱進行檢查。",
  "Bring a reference ad and say what to change: new images in its exact style, with your product and brand.": "帶來一則參考廣告並說明要改什麼：用完全相同的風格，搭配你的產品和品牌生成新圖片。",
  "Send approved creatives to Meta as paused drafts, and promote the winners to scaling.": "以暫停的草稿形式把核准的素材送到 Meta，並把贏家推進擴量。",
  "Ad spend next to what it brought in, per campaign and creative.": "依行銷活動和素材，並列呈現廣告花費與帶來的收益。",
  "The accounts this app's pages connect to (now the Brand page's Settings tab).": "這個 App 各頁面連接的帳號（現為品牌頁面的「設定」分頁）。",
