  "Impressions: <100. Meta's lowest bucket in the Ad Library, so this ad has barely been shown.": "曝光次數：<100。這是 Meta 廣告檔案庫中最低的級距，代表這則廣告幾乎沒有播放。",
  "In Meta's impressions order: #1 was shown the most.": "依 Meta 的曝光排序：#1 曝光最多。",
