  "It comes off the list.": "它會從清單移除。",
  "Its place under Meta's “total impressions” sort when {name}'s ads were collected (#1 had the most).": "收集 {name} 的廣告時，它在 Meta「總曝光次數」排序中的名次（#1 曝光最多）。",
  "Its script, shots and hook": "腳本、鏡頭與開場鉤子",
  "Its website finds every Google ad that links to it. For one exact account, search the brand on adstransparency.google.com, open the advertiser and copy the link (it has AR… in it).": "用網站可以找到所有連到它的 Google 廣告。若要指定單一帳號，請在 adstransparency.google.com 搜尋品牌、開啟廣告主並複製連結（連結中含 AR…）。",
  "Joins your competitor list": "加入競品清單",
