  "Live": "投放中",
  "Low impression count": "曝光次數低",
  "Make this for {app} gives you a ready-made prompt for this kind of ad with your brand in it, a one-click image here, or a full batch in Studio ({placement}). Their name, logo, people and words are never copied.": "「為 {app} 製作」會給你一段已放入你品牌的同類廣告提示詞、在這裡一鍵生成圖片，或在 Studio 產生一整批（{placement}）。對方的名稱、標誌、人物與文字都不會被複製。",
  "Make this for {app}": "為 {app} 製作",
  "Measuring…": "測量中…",
  "Media link expired: collect the ads again": "媒體連結已過期：請重新收集廣告",
  "Media link expired: pull the ads again": "媒體連結已過期：請重新擷取廣告",
  "Media to store": "要儲存的媒體",
  "Meta and Google ads in any country, and TikTok ads shown in Europe, with your own keys. Billed per ad by Apify; you see the sources and the most it can cost before each collection.": "用你自己的金鑰收集任何國家的 Meta 與 Google 廣告，以及在歐洲播放的 TikTok 廣告。Apify 依廣告數計費；每次收集前都會先顯示來源與最高可能費用。",
  "Meta flagged this run. The extension started a 6-hour cooldown; don't collect again before 6 hours have passed.": "Meta 標記了這次執行。擴充功能已開始 6 小時冷卻；6 小時內請勿再次收集。",
  "Meta flagged this run. The extension started a 6-hour cooldown; don't collect again before {time}.": "Meta 標記了這次執行。擴充功能已開始 6 小時冷卻；{time} 前請勿再次收集。",
  "Meta's Ad Library API": "Meta 廣告檔案庫 API",
  "Meta's impressions order compares ads within one advertiser: pick one to see their order.": "Meta 的曝光排序只能比較同一個廣告主的廣告：選一個廣告主即可查看排序。",
  "Meta's impressions order": "Meta 曝光排序",
  "Named by the AI profile": "由 AI 簡介提出",
  "Nearest Meta placement · {where}": "最接近的 Meta 版位 · {where}",
  "Network": "平台",
  "New ads by the day they started running (the Ad Library's start date)": "依開始投放的日期篩選新廣告（廣告檔案庫的開始日期）",
