  "No copy to read yet. Collect its ads again to get its text.": "目前沒有可解讀的文案。請重新收集它的廣告以取得文字。",
  "No creatives stored yet": "尚未儲存任何素材",
  "No creatives stored": "沒有儲存的素材",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on Research.": "付費廣告不需要金鑰：用廣告檔案庫擴充功能收集競品的廣告，再到研究頁面匯入檔案。",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on your app's Research page.": "付費廣告不需要金鑰：用廣告檔案庫擴充功能收集競品的廣告，再到你 App 的研究頁面匯入檔案。",
  "No media to measure.": "沒有可測量的媒體。",
  "No preview": "沒有預覽",
