  "Not an ads file": "不是廣告檔案",
  "Not enough room: {n} file ({size}) will be left behind.": "空間不足：{n} 個檔案（{size}）不會儲存。",
  "Not enough room: {n} files ({size}) will be left behind.": "空間不足：{n} 個檔案（{size}）不會儲存。",
  "Not read yet.": "尚未解讀。",
  "Not read yet: new ads are read in the background, a few at a time.": "尚未解讀：新廣告會在背景一次解讀幾則。",
  "Nothing to import": "沒有可匯入的內容",
  "Once the TypeSafe key is set, the AI reads each new ad for its format and hook, automatically, billed by TypeSafe.": "設定 TypeSafe 金鑰後，AI 會自動解讀每則新廣告的格式與開場鉤子，由 TypeSafe 計費。",
  "Once your OpenAI key is set, each new ad is read for its format and hook automatically:": "設定 OpenAI 金鑰後，每則新廣告都會自動解讀格式與開場鉤子：",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and each one's imported ads are filed under it.": "整個 App 共用一份競品清單：素材檢查會避免你的廣告出現這些名稱，每個競品匯入的廣告也會歸在它底下。",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and followed ones are included when you collect automatically.": "整個 App 共用一份競品清單：素材檢查會避免你的廣告出現這些名稱，自動收集時也會包含追蹤中的競品。",
  "One per creative": "每個素材只顯示一則",
  "Only the first {max} ads are imported, so no ads are marked as stopped.": "只會匯入前 {max} 則廣告，因此不會有廣告被標記為已停止。",
  "Open ad from {name}": "開啟 {name} 的廣告",
  "Open in Ad Library ↗": "在廣告檔案庫開啟 ↗",
  "Open in TikTok ↗": "在 TikTok 開啟 ↗",
