  "Open or Search": "開啟或搜尋",
  "Open the brand's Facebook Page or its page in the Meta Ad Library and copy the link. Without one, its name is searched.": "開啟品牌的 Facebook 粉絲專頁或它在 Meta 廣告檔案庫的頁面，並複製連結。沒有連結時會改用名稱搜尋。",
  "Open your Facebook Page in the Ad Library, collect its ads with the Ad Library extension, then drop the file here and choose “Ours”.": "在廣告檔案庫開啟你的 Facebook 粉絲專頁，用廣告檔案庫擴充功能收集廣告，再把檔案拖放到這裡並選擇「我們的」。",
  "Opens the Studio with a brief from what your top long-runners of a kind share (format, hook, proof, offer, CTA, layout), their images as style references and their offer wording. Every new ad still gets a new hook.": "開啟 Studio，並帶入一份簡報：同類型中長期投放的頂尖廣告的共通點（格式、開場鉤子、佐證、優惠、CTA、版面）、作為風格參考的圖片，以及優惠文案。每則新廣告仍會有新的開場鉤子。",
  "Other advertisers": "其他廣告主",
