  "Paid ads your competitors are running now. The longer an ad runs and the more copies of it are live, the more likely it's working. Each new ad is read for its format, hook and structure on its own.": "競品目前正在投放的付費廣告。投放越久、同時投放的份數越多，越可能有效。每則新廣告都會自動解讀格式、開場鉤子與結構。",
  "Partnership ad with {name}": "與 {name} 的合作廣告",
  "Partnership": "合作夥伴",
  "Pick a competitor above the ads to see theirs in Meta's impressions order.": "在廣告上方選一個競品，即可依 Meta 的曝光排序查看他們的廣告。",
