  "Ranked #{rank} at {age}; an ad that age usually ranks about #{expected} ({curve}).": "投放 {age} 時排第 #{rank}；同齡的廣告通常約排第 #{expected}（{curve}）。",
  "Read from the ad copy. Scanning it in Recreate hears the video, and it's read again from what's said.": "依廣告文案解讀。在重製中掃描會聽取影片內容，並依口白重新解讀。",
