  "Saved {n} ad from {name} to Competitors' ads: {created} new, {updated} updated.": "已將 {name} 的 {n} 則廣告存到「競品的廣告」：新增 {created} 則，更新 {updated} 則。",
  "Saved {n} ad from {name} to Our ads: {created} new, {updated} updated.": "已將 {name} 的 {n} 則廣告存到「我們的廣告」：新增 {created} 則，更新 {updated} 則。",
  "Saved {n} ads from {name} to Competitors' ads: {created} new, {updated} updated.": "已將 {name} 的 {n} 則廣告存到「競品的廣告」：新增 {created} 則，更新 {updated} 則。",
  "Saved {n} ads from {name} to Our ads: {created} new, {updated} updated.": "已將 {name} 的 {n} 則廣告存到「我們的廣告」：新增 {created} 則，更新 {updated} 則。",
  "Saving creatives to storage: {done} of {n} file ({size})": "正在將素材存到儲存空間：{n} 個檔案中已完成 {done} 個（{size}）",
  "Saving creatives to storage: {done} of {n} files ({size})": "正在將素材存到儲存空間：{n} 個檔案中已完成 {done} 個（{size}）",
  "Saving {n} image and video file to storage in the background ({stored} already saved).": "正在背景將 {n} 個圖片與影片檔案存到儲存空間（已儲存 {stored} 個）。",
  "Saving {n} image and video file to storage in the background.": "正在背景將 {n} 個圖片與影片檔案存到儲存空間。",
  "Saving {n} image and video files to storage in the background ({stored} already saved).": "正在背景將 {n} 個圖片與影片檔案存到儲存空間（已儲存 {stored} 個）。",
  "Saving {n} image and video files to storage in the background.": "正在背景將 {n} 個圖片與影片檔案存到儲存空間。",
  "Scaled creatives": "已擴量的素材",
  "Search terms": "搜尋字詞",
  "Search the brand on library.tiktok.com with a European country picked, then paste the advertiser name it shows, or the link. TikTok lists ads shown in Europe only.": "在 library.tiktok.com 選擇一個歐洲國家後搜尋品牌，再貼上顯示的廣告主名稱或連結。TikTok 只列出在歐洲播放的廣告。",
  "Send to format library": "傳送到格式庫",
  "Send to library": "傳送到格式庫",
  "Send to the format library": "傳送到格式庫",
  "Sensitive content": "敏感內容",
  "Since": "起始日",
  "Statics and Videos sort by Meta's impressions order.": "靜態廣告與影片會依 Meta 的曝光排序。",
  "Statics like our top {n}": "像我們前 {n} 名的靜態廣告",
  "Statics": "靜態圖",
  "Stopped early": "提早中止",
  "Stopped early: {reason}": "提早中止：{reason}",
  "Stopped": "已停止",
  "Stored media": "已儲存的媒體",
  "Strongest": "表現最強",
  "Suggested": "建議",
  "That file isn't JSON. Pick a .json file the Ad Library extension saved.": "這個檔案不是 JSON。請選擇廣告檔案庫擴充功能儲存的 .json 檔。",
  "That isn't a file from the Ad Library extension. Drop the .json file it saved in Downloads/Ad Library, unchanged.": "這不是廣告檔案庫擴充功能產生的檔案。請拖放它存在 Downloads/Ad Library 的 .json 檔，不要修改。",
  "That's not an ads file: choose the .json files the Ad Library extension saved.": "這不是廣告檔案：請選擇廣告檔案庫擴充功能儲存的 .json 檔。",
  "That's not an ads file: drop the .json files the Ad Library extension saved.": "這不是廣告檔案：請拖放廣告檔案庫擴充功能儲存的 .json 檔。",
  "The AI then reads each new ad for its format and hook, automatically, billed by TypeSafe.": "接著 AI 會自動解讀每則新廣告的格式與開場鉤子，由 TypeSafe 計費。",
  "The Ad Library extension": "廣告檔案庫擴充功能",
  "The ad couldn't be read.": "無法解讀這則廣告。",
  "The ads go up in parts of up to {n}: keep this tab open until the import finishes.": "廣告會分批上傳，每批最多 {n} 則：匯入完成前請保持這個分頁開啟。",
  "The advertiser name in TikTok's Ad Library": "TikTok 廣告檔案庫中的廣告主名稱",
  "The collection stopped early, so no ads are marked as stopped.": "這次收集提早中止，因此不會有廣告被標記為已停止。",
  "The collectors couldn't be checked just now. Importing files works as usual; reload to check again.": "目前無法檢查收集工具。匯入檔案仍可正常使用；重新整理即可再次檢查。",
  "The file has no ads. Check the Ad Library page and collect again.": "檔案中沒有廣告。請檢查廣告檔案庫頁面後重新收集。",
  "The images and videos are deleted from storage. The ads stay in the list and fall back to their Ad Library links, which stop working after a few days. Collect the ads again and import the file to save them again.": "圖片與影片會從儲存空間刪除。廣告仍留在清單中，改用廣告檔案庫的連結，但這些連結幾天後就會失效。重新收集廣告並匯入檔案，即可再次儲存。",
  "The import stopped": "匯入已中止",
  "The order under Meta's \"total impressions\" sort when the ads were collected; ranks compare within one advertiser": "收集廣告時 Meta「總曝光次數」排序的順序；名次只在同一個廣告主內比較",
  "Their ads, copy and posters still are. Freeing space doesn't change this per-file limit; it's your Supabase project's upload limit (Storage settings).": "它們的廣告、文案與封面仍會儲存。釋出空間不會改變這個單檔上限；這是你 Supabase 專案的上傳上限（Storage 設定）。",
  "Their images and videos are saved to storage in the background so they don't expire.": "它們的圖片與影片會在背景存到儲存空間，避免連結過期。",
  "Their images and videos couldn't be queued for storage: {error}": "無法將它們的圖片與影片排入儲存佇列：{error}",
  "There's no setting to turn this off.": "這項功能無法關閉。",
  "This import stores {n} file ({size}).": "這次匯入會儲存 {n} 個檔案（{size}）。",
  "This import stores {n} file ({size}); {stored} are already stored and are skipped.": "這次匯入會儲存 {n} 個檔案（{size}）；已儲存的 {stored} 個會略過。",
  "This import stores {n} files ({size}).": "這次匯入會儲存 {n} 個檔案（{size}）。",
  "This import stores {n} files ({size}); {stored} are already stored and are skipped.": "這次匯入會儲存 {n} 個檔案（{size}）；已儲存的 {stored} 個會略過。",
  "TikTok ads": "TikTok 廣告",
  "TikTok advertiser id": "TikTok 廣告主 ID",
  "TikTok business (TikTok ads)": "TikTok 商家（TikTok 廣告）",
  "Top ad · CTR {pct}%": "熱門廣告 · CTR {pct}%",
  "Track when its ads were last collected": "追蹤它的廣告最後收集的時間",
  "Tracking": "追蹤參數",
  "Two-letter codes, for automatic collection.": "兩個字母的國家代碼，用於自動收集。",
  "Two-letter codes. EU and UK ads come from Meta's free API.": "兩個字母的國家代碼。歐盟與英國的廣告來自 Meta 的免費 API。",
  "Unknown: the media link has expired.": "未知：媒體連結已過期。",
  "Video {n}": "影片 {n}",
  "Videos like our top {n}": "像我們前 {n} 名的影片廣告",
  "Website or Google advertiser (Google ads)": "網站或 Google 廣告主（Google 廣告）",
  "What to do:": "建議做法：",
  "Whether the AI scan found the ad fits what you sell: advice only": "AI 掃描判斷這則廣告是否適合你販售的產品：僅供參考",
  "Whose ads are these?": "這些是誰的廣告？",
  "Whose ads": "誰的廣告",
  "Whose ads: {name}": "誰的廣告：{name}",
  "With your OpenAI key set, each new ad is then read for its format and hook automatically:": "已設定 OpenAI 金鑰，接著每則新廣告都會自動解讀格式與開場鉤子：",
