  "{each} an ad at OpenAI, up to {total} for {n} ads (an estimate at {model} prices; ads read before aren't read again).": "OpenAI 每則廣告 {each}，{n} 則最多 {total}（依 {model} 價格估算；已解讀過的廣告不會重複解讀）。",
