  "{n} ads not read yet for format, hook and structure: reading needs {keys}. The rest of this page works without it.": "{n} 則廣告尚未解讀格式、開場鉤子與結構：解讀需要 {keys}。這個頁面的其他功能不受影響。",
  "{n} ads saved": "已儲存 {n} 則廣告",
