  "{n} file ({size}) is over the {limit} upload limit and won't be stored.": "{n} 個檔案（{size}）超過 {limit} 的上傳上限，不會儲存。",
  "{n} file couldn't be saved. Either its link expired before it was saved (collect the advertiser's ads again and import the file), or it's a video over the storage upload limit, which isn't stored (its ad and poster are).": "{n} 個檔案無法儲存。可能是連結在儲存前已過期（請重新收集該廣告主的廣告並匯入檔案），或是超過儲存空間上傳上限的影片，這類影片不會儲存（廣告與封面仍會儲存）。",
  "{n} file didn't report a size, so it's estimated.": "{n} 個檔案沒有回報大小，因此以估算計。",
  "{n} file stored ({size}) — kept until you delete them": "已儲存 {n} 個檔案（{size}）— 會保留到你刪除為止",
  "{n} files ({size}) are over the {limit} upload limit and won't be stored.": "{n} 個檔案（{size}）超過 {limit} 的上傳上限，不會儲存。",
  "{n} files couldn't be saved. Either their link expired before they were saved (collect the advertiser's ads again and import the file), or they're videos over the storage upload limit, which aren't stored (their ads and posters are).": "{n} 個檔案無法儲存。可能是連結在儲存前已過期（請重新收集該廣告主的廣告並匯入檔案），或是超過儲存空間上傳上限的影片，這類影片不會儲存（廣告與封面仍會儲存）。",
  "{n} files didn't report a size, so they're estimated.": "{n} 個檔案沒有回報大小，因此以估算計。",
  "{n} files stored ({size}) — kept until you delete them": "已儲存 {n} 個檔案（{size}）— 會保留到你刪除為止",
