  "POV / skit": "POV／短劇",
  "Pacing and length": "節奏與長度",
  "Pacing": "節奏",
  "Paste it into ChatGPT, Higgsfield or another tool. No key needed.": "貼到 ChatGPT、Higgsfield 或其他工具，不需要金鑰。",
  "Person": "人物",
  "Person's name": "人名",
  "Phone number": "電話號碼",
  "Pick up to {max}; none are picked for you.": "最多可選 {max} 張；不會替你預先選取。",
  "Pick {name}": "選取 {name}",
  "Picked images go to Higgsfield after their ad; the scene is rebuilt around them, not pasted on.": "選取的圖片會接在他們的廣告之後送到 Higgsfield；場景會圍繞這些圖片重建，而不是直接貼上。",
  "Picked images go to Higgsfield as references; the scene is rebuilt around them, not pasted on.": "選取的圖片會作為參考送到 Higgsfield；場景會圍繞這些圖片重建，而不是直接貼上。",
  "Place our logo on the finished image": "把我們的 Logo 放到完成的圖片上",
  "Policy check passed": "政策檢查通過",
  "Post copy": "貼文文案",
  "Prefilled from your Brand. Every field overrides their ad.": "已依你的品牌預先填入。每個欄位都會覆蓋他們的廣告。",
  "Prefilled with their text; yours now.": "已預先填入他們的文字；現在由你接手。",
  "Prefilled with their words: rewrite them in yours.": "已預先填入他們的文字：請用你的話改寫。",
  "Price or offer": "價格或優惠",
  "Price, offer or code": "價格、優惠或折扣碼",
  "Product demo": "產品示範",
  "Promise a count, then deliver each item fast with a number on screen.": "先承諾一個數量，再快速逐一呈現，每項都在畫面標上編號。",
  "Promise a count, then deliver it in order.": "先承諾一個數量，再依序呈現。",
  "Promise one outcome, then walk through it in clear numbered steps on screen.": "承諾一個成果，再用畫面上清楚編號的步驟帶大家完成。",
  "Prompt for": "提示詞用於",
  "Put the old way next to the better way and let the difference show.": "把舊方法和更好的方法並排，讓差異自己說話。",
  "Queue it": "加入佇列",
  "Queued {n} job for about {credits} credits.": "已將 {n} 個工作加入佇列，約 {credits} 點。",
  "Queued {n} jobs for about {credits} credits.": "已將 {n} 個工作加入佇列，約 {credits} 點。",
  "Quiz / result reveal": "測驗／揭曉結果",
  "React to a relatable prompt (a question, a headline you write yourself), then answer it with the product.": "對一個有共鳴的題目做出反應（一個問題、一個你自己寫的標題），再用產品來回答。",
  "Reaction": "反應",
  "Read it again": "重新解讀",
  "Read the ad (the link at the top) to list what changes: their name and wordmark, product, claims and every line of text.": "讀取廣告（上方的連結），列出要改的內容：他們的名稱與字標、產品、主張和每一行文字。",
  "Read the ad again to check whether it fits what you sell (advice only).": "重新讀取廣告，檢查它是否符合你賣的東西（僅供參考）。",
  "Read the ad to check whether it fits what you sell (advice only).": "讀取廣告，檢查它是否符合你賣的東西（僅供參考）。",
  "Read the ad": "讀取廣告",
  "Read the whole video": "讀取整支影片",
  "Read {date} (the poster frame only)": "{date} 已讀取（僅封面影格）",
  "Read {date}": "{date} 已讀取",
  "Reading it again needs {keys}": "重新讀取需要 {keys}",
  "Reading the video and its audio…": "正在讀取影片與音訊…",
