  "Reading their ad needs {keys}": "讀取他們的廣告需要 {keys}",
  "Reading their ad…": "正在讀取他們的廣告…",
  "Reading their video to tell a presenter-to-camera ad from an animated or demo one…": "正在讀取他們的影片，判斷是出鏡者對鏡頭的廣告，還是動畫或示範影片…",
  "Ready-made prompt": "現成的提示詞",
  "Real review quotes and ratings carry the ad. Only real, consented reviews.": "由真實的評論引言與評分撐起整則廣告。只能使用真實且經同意的評論。",
  "Rebuild from the fields": "依欄位重建",
