  "You edited the prompt, so it doesn't describe these images yet: rebuild it from the fields.": "你編輯過提示詞，所以它還沒有描述這些圖片：請依欄位重建。",
  "You edited the prompt: changes to the fields don't reach it until you rebuild it.": "你編輯過提示詞：在重建之前，欄位的變更不會套用。",
