  "Your preferences. They win over matching their ad.": "你的偏好。會優先於照搬他們的廣告。",
  "Your version follows its layout and style ({level}, set by Closeness) while every brand detail becomes yours; your screenshots go after it. Exact needs it.": "你的版本會依循它的版面與風格（{level}，由「相似度」決定），所有品牌細節則換成你的；你的截圖會排在它後面。「完全一致」必須使用它。",
