  "the same format and placement only; layout and copy are ours to choose": "只保留相同的格式與版位；版面與文案由我們決定",
  "the same layout, composition, text placement and copy rhythm, with our brand, colours and people": "相同的版面、構圖、文字位置與文案節奏，搭配我們的品牌、顏色與人物",
