  "{name} couldn't make it: {error}": "{name} 無法製作：{error}",
  "{name} didn't accept the key. Check it in Settings › Your keys, then retry.": "{name} 不接受這把金鑰。請到「設定 › 你的金鑰」檢查後再重試。",
  "{name} is busy right now (too many requests). Wait a minute and retry, or switch provider.": "{name} 目前忙碌中（請求過多）。請稍等一分鐘再重試，或改用其他供應商。",
  "{name} refused the prompt under its content rules. Edit the prompt (fewer claims, no people or brands) and retry.": "{name} 依其內容規範拒絕了這個提示詞。請修改提示詞（減少主張、不放人物或品牌）後再重試。",
  "{name} says the account is out of credits or over its limit. Top it up on {name}'s site, then retry, or switch provider.": "{name} 表示帳號點數不足或已超過上限。請到 {name} 網站儲值後再重試，或改用其他供應商。",
  "{name} took too long for this Supabase plan. Retry with a lower quality or resolution.": "{name} 花費的時間超過這個 Supabase 方案的上限。請用較低的品質或解析度重試。",
