  "Our ads live 45+ days, oldest first: likely wearing out, so make the next version before they stop": "我們投放 45 天以上的廣告，最舊的排前面：很可能已經疲乏，趁停止前先做出下一版",
  "Our ads live {n}+ days: likely wearing out, so make the next version before they stop": "我們投放 {n} 天以上的廣告：很可能已經疲乏，趁停止前先做出下一版",
  "POV skit": "POV 短劇",
  "Paid-ads research isn't set up in the database yet (migration 20261002300000_paid_ads).": "資料庫尚未設定付費廣告研究（migration 20261002300000_paid_ads）。",
  "Parallel or back-to-back sessions from one connection are a common reason Meta blocks it for hours.": "從同一個網路連線同時或連續進行收集，是 Meta 封鎖數小時的常見原因。",
  "Partnership ads (run with a creator's or another Page) live 30+ days": "投放 30 天以上的合作廣告（與創作者或其他粉絲專頁一起投放）",
  "Partnership ads": "合作廣告",
  "Paste the Page's link (facebook.com/…), its Ad Library link, or its numeric Page id.": "請貼上粉絲專頁連結（facebook.com/…）、它的廣告檔案庫連結，或數字粉絲專頁 ID。",
  "Paste the advertiser's name as TikTok's Ad Library shows it, or a library.tiktok.com link with its business id.": "請貼上 TikTok 廣告檔案庫顯示的廣告主名稱，或含商家 ID 的 library.tiktok.com 連結。",
  "Paste the competitor's website (like notion.so) or its advertiser link from adstransparency.google.com.": "請貼上競品的網站（例如 notion.so），或 adstransparency.google.com 上的廣告主連結。",
  "Proven winners": "已驗證的勝出廣告",
  "Ran 30+ days, then stopped: a former winner that wore out": "投放 30 天以上後停止：曾經勝出、後來疲乏的廣告",
  "Ran 30+ days, then stopped: what worked until it didn't, and angles they may come back to": "投放 30 天以上後停止：曾經有效、後來失效的廣告，也是他們可能再回頭使用的切角",
  "Reading the ads with AI": "用 AI 解讀廣告",
