  "Research answered {status}. Try again in a moment.": "研究服務回應了 {status}，請稍後再試。",
  "Run with a creator or another Page (Meta's branded content): who they pay to post for them": "與創作者或其他粉絲專頁一起投放（Meta 的品牌置入內容）：他們付費請誰幫忙發文",
  "Runs started less than 30 min apart ({n} min at the closest).": "收集的開始時間間隔不到 30 分鐘（最短 {n} 分鐘）。",
  "Scaled": "已加碼",
  "See details": "查看詳情",
  "Send message": "傳送訊息",
  "Settings › Research sources": "設定 › 研究來源",
  "Share of live ads running 30+ days": "投放中廣告裡已投放 30 天以上的比例",
  "Share of live ads that are video": "投放中廣告裡影片的比例",
  "Share still running, of the ads first seen here {n}+ days ago ({name} only): a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "在 {n} 天以前首次出現在這裡的廣告中仍在投放的比例（僅限 {name}）：比例越高，代表廣告主越願意持續為這類廣告付費。少於 10 則廣告的分組不列入。每次匯入都會讓結果更準確。",
  "Share still running, of the ads first seen here {n}+ days ago: a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "在 {n} 天以前首次出現在這裡的廣告中仍在投放的比例：比例越高，代表廣告主越願意持續為這類廣告付費。少於 10 則廣告的分組不列入。每次匯入都會讓結果更準確。",
  "Show all the text": "顯示全部文字",
  "Show {name}'s ads": "顯示 {name} 的廣告",
  "Silent text": "無聲文字",
  "Started in the last 7 days": "最近 7 天內開始",
  "Static benefit image": "靜態效益圖",
  "Still live and started 30+ days ago: an advertiser that keeps paying for an ad is telling you it works": "仍在投放且已開始 30 天以上：廣告主持續為一則廣告付費，代表它有效",
  "Stopped after 30+ days": "投放 30 天以上後停止",
  "Stopped after running under 21 days: most likely a test that lost": "投放不到 21 天就停止：很可能是落敗的測試",
  "Stopped in the last 14 days": "最近 14 天內停止",
  "Stopped in the last 14 days: gone from the Ad Library since an earlier import": "最近 14 天內停止：在上次匯入後已從廣告檔案庫消失",
  "Stopped within 21 days": "21 天內停止",
  "Stopped within 21 days: what didn't work for them": "21 天內停止：對他們無效的廣告",
  "Stopped · 14d": "停止 · 14 天",
  "Switched off: {sources}. Turn them on in {link}.": "已關閉：{sources}。請到{link}開啟。",
  "That Transparency Center link has no advertiser in it. Open the advertiser's page and copy its link (it has AR… in it).": "這個透明中心連結裡沒有廣告主。請開啟廣告主頁面並複製它的連結（連結中會有 AR…）。",
  "That doesn't look like a Facebook Page id or facebook.com link.": "這看起來不像 Facebook 粉絲專頁 ID 或 facebook.com 連結。",
  "That isn't a JSON file.": "這不是 JSON 檔案。",
  "That upload is over 10 MB. Reload the page (a current Research page sends a big file in parts) and import it again.": "上傳的檔案超過 10 MB。請重新載入頁面（新版研究頁面會把大檔案分段傳送），再匯入一次。",
  "The .json files the Ad Library extension saves: one per Page, as many as you like at once.": "廣告檔案庫擴充功能儲存的 .json 檔案：每個粉絲專頁一個，一次可以放多個。",
  "The .json files the Ad Library extension saves: one per competitor, as many as you like at once.": "廣告檔案庫擴充功能儲存的 .json 檔案：每個競品一個，一次可以放多個。",
  "The Ad Library link expired before this file was saved": "廣告檔案庫的連結在這個檔案儲存前就過期了",
  "The earlier versions couldn't be loaded.": "無法載入舊版本。",
  "The extension collects one competitor at a time, at least 30 minutes apart, and stops for 6 hours if Meta shows a block sign. It runs in its own small window: keep part of it visible while you work elsewhere.": "擴充功能一次收集一個競品，每次間隔至少 30 分鐘；若 Meta 出現封鎖跡象，會暫停 6 小時。它在自己的小視窗中執行：你在做其他事時，請讓它保持部分可見。",
