  "Text on screen": "畫面文字",
  "The AI names the brands you're up against with their social accounts, checks each one against your app, and you pick who to study.": "AI 會列出你面對的品牌與它們的社群帳號，逐一和你的 App 比對，再由你挑選要研究的對象。",
  "The account": "帳號",
  "The analysis, all its runs and their reports are deleted for good.": "這項分析、所有執行及其報告都會永久刪除。",
  "The app reads the brand's tagged posts and collab posts, then checks creators' bios for ties like “athlete @brand”, “ambassador” or a discount code. Posts from those creators count even when they don't tag the brand. Adds about $1.40.": "App 會讀取品牌被標記的貼文與合作貼文，再檢查創作者簡介中是否有「athlete @brand」、「ambassador」或折扣碼等關係。即使這些創作者沒有標記品牌，他們的貼文也會計入。約增加 $1.40。",
  "The best came from {account}.": "最佳貼文來自 {account}。",
